:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --card:#1e2240;
  --text:#eef0ff;
  --muted:#b8bce6;
  --accent:#8be9fd;
  --warn:#ffb86c;
  --ok:#50fa7b;
  --bad:#ff5555;
  --line:rgba(255,255,255,.10);
}
*{box-sizing:border-box}
body{
  margin:0;
  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Arial, "Noto Sans", "Liberation Sans", sans-serif;
  background: radial-gradient(1200px 700px at 20% 0%, #1a1f3a 0%, var(--bg) 55%);
  color:var(--text);
}
.wrap{max-width:980px;margin:0 auto;padding:22px 16px 28px}
header h1{margin:0 0 6px;font-size:22px;letter-spacing:.2px}
.sub{margin:0 0 14px;color:var(--muted);line-height:1.35}
.ex{color:var(--accent);font-weight:600}
.panel{
  background: linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
  border:1px solid var(--line);
  border-radius:14px;
  padding:14px;
  box-shadow: 0 10px 30px rgba(0,0,0,.25);
}
.row{display:flex;flex-direction:column;gap:6px;margin-bottom:12px}
.row.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}
label{font-size:12px;color:var(--muted)}
input, select{
  width:100%;
  padding:10px 12px;
  border-radius:10px;
  border:1px solid var(--line);
  background: rgba(0,0,0,.18);
  color:var(--text);
  outline:none;
}
input:focus, select:focus{border-color: rgba(139,233,253,.55); box-shadow: 0 0 0 3px rgba(139,233,253,.12)}
.btns{display:flex;gap:10px;flex-wrap:wrap;margin:6px 0 12px}
button{
  border:1px solid rgba(255,255,255,.14);
  background: rgba(139,233,253,.14);
  color:var(--text);
  padding:9px 12px;
  border-radius:10px;
  cursor:pointer;
  font-weight:650;
}
button:hover{border-color: rgba(139,233,253,.55)}
button.ghost{background: rgba(255,255,255,.06)}
.out{display:grid;grid-template-columns:repeat(3, 1fr);gap:10px}
.card{
  background: rgba(0,0,0,.16);
  border:1px solid var(--line);
  border-radius:12px;
  padding:10px 12px;
  min-height:66px;
}
.card.wide{grid-column:1 / -1; min-height:92px}
.k{font-size:11px;color:var(--muted);margin-bottom:6px}
.v{font-size:14px;line-height:1.25}
.v.big{font-size:20px;letter-spacing:.2px}
.why{margin-top:6px;color:var(--muted);font-size:12px;line-height:1.35}
.help{margin-top:12px;border-top:1px solid var(--line);padding-top:10px;color:var(--muted)}
.help summary{cursor:pointer;color:var(--text);font-weight:700}
.help ul{margin:8px 0 0 18px}
footer{margin-top:12px;color:var(--muted)}
.mini{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.chip{
  padding:6px 10px;
  border-radius:999px;
  background: rgba(255,255,255,.06);
  border:1px solid var(--line);
  font-weight:650;
}
.chip:hover{border-color: rgba(255,255,255,.28)}
@media (max-width:720px){
  .row.two{grid-template-columns:1fr}
  .out{grid-template-columns:1fr}
  .card.wide{grid-column:auto}
}

